import { test, expect } from '@playwright/test';

test.describe('Modal Scroll Lock', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body style="height: 200vh; margin: 0;"><div style="height: 100vh; background: lightblue; display: flex; align-items: center; justify-content: center;"><h1>Scrollable Content</h1></div><button id="openModal">Open Modal</button><div id="modal" style="display: none; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 300px; height: 200px; background: white; border: 2px solid black; z-index: 1000; padding: 20px;"><h2>Modal Dialog</h2><p>This is a modal</p><button id="closeModal">Close Modal</button></div><div id="overlay" style="display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 999;"></div><script>const modal = document.getElementById("modal"); const overlay = document.getElementById("overlay"); const openBtn = document.getElementById("openModal"); const closeBtn = document.getElementById("closeModal"); openBtn.addEventListener("click", () => { modal.style.display = "block"; overlay.style.display = "block"; document.body.style.overflow = "hidden"; }); closeBtn.addEventListener("click", () => { modal.style.display = "none"; overlay.style.display = "none"; document.body.style.overflow = "auto"; }); </script></body></html>');
  });

  test('should prevent page scroll when modal is open', async ({ page }) => {
    // Get initial scroll position
    const initialScroll = await page.evaluate(() => window.scrollY);
    expect(initialScroll).toBe(0);

    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Try to scroll the page
    await page.evaluate(() => window.scrollBy(0, 500));

    // Verify scroll position hasn't changed
    const scrollAfterAttempt = await page.evaluate(() => window.scrollY);
    expect(scrollAfterAttempt).toBe(0);
  });

  test('should allow page scroll after modal is closed', async ({ page }) => {
    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Close the modal
    await page.getByRole('button', { name: 'Close Modal' }).click();

    // Verify modal is hidden
    await expect(modal).not.toBeVisible();

    // Try to scroll the page
    await page.evaluate(() => window.scrollBy(0, 500));

    // Verify scroll position has changed
    const scrollAfterClose = await page.evaluate(() => window.scrollY);
    expect(scrollAfterClose).toBeGreaterThan(0);
  });

  test('should verify body overflow style is hidden when modal is open', async ({ page }) => {
    // Get initial overflow style
    const initialOverflow = await page.evaluate(() => window.getComputedStyle(document.body).overflow);
    expect(initialOverflow).toBe('visible');

    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify body overflow is hidden
    const overflowHidden = await page.evaluate(() => window.getComputedStyle(document.body).overflow);
    expect(overflowHidden).toBe('hidden');

    // Close the modal
    await page.getByRole('button', { name: 'Close Modal' }).click();

    // Verify body overflow is restored
    const overflowRestored = await page.evaluate(() => window.getComputedStyle(document.body).overflow);
    expect(overflowRestored).toBe('visible');
  });
});
